#include <iostream>
#include <cmath>
using namespace std;

int binToDec(long long n) {
    int dec = 0, i = 0;
    while (n != 0) {
        int r = n % 10;
        dec += r * pow(2, i);
        n /= 10;
        i++;
    }
    return dec;
}

int octToDec(long long n) {
    int dec = 0, i = 0;
    while (n != 0) {
        int r = n % 10;
        dec += r * pow(8, i);
        n /= 10;
        i++;
    }
    return dec;
}

int hexToDec(string hex) {
    int dec = 0, base = 1;
    for (int i = hex.length() - 1; i >= 0; i--) {
        if (hex[i] >= '0' && hex[i] <= '9')
            dec += (hex[i] - 48) * base;
        else if (hex[i] >= 'A' && hex[i] <= 'F')
            dec += (hex[i] - 55) * base;
        base *= 16;
    }
    return dec;
}

string decToBin(int n) {
    string res = "";
    while (n > 0) {
        res = char(n % 2 + '0') + res;
        n /= 2;
    }
    return res == "" ? "0" : res;
}

string decToOct(int n) {
    string res = "";
    while (n > 0) {
        res = char(n % 8 + '0') + res;
        n /= 8;
    }
    return res == "" ? "0" : res;
}

string decToHex(int n) {
    string res = "";
    char hex[] = "0123456789ABCDEF";
    while (n > 0) {
        res = hex[n % 16] + res;
        n /= 16;
    }
    return res == "" ? "0" : res;
}

int main() {
    int choice;
    cout << "1. Decimal to Binary\n2. Decimal to Octal\n3. Decimal to Hexadecimal\n";
    cout << "4. Binary to Decimal\n5. Octal to Decimal\n6. Hexadecimal to Decimal\n";
    cout << "7. Binary to Octal\n8. Binary to Hexadecimal\nEnter choice: ";
    cin >> choice;

    if (choice == 1) {
        int n; cout << "Enter decimal: "; cin >> n;
        cout << decToBin(n);
    } else if (choice == 2) {
        int n; cout << "Enter decimal: "; cin >> n;
        cout << decToOct(n);
    } else if (choice == 3) {
        int n; cout << "Enter decimal: "; cin >> n;
        cout << decToHex(n);
    } else if (choice == 4) {
        long long n; cout << "Enter binary: "; cin >> n;
        cout << binToDec(n);
    } else if (choice == 5) {
        long long n; cout << "Enter octal: "; cin >> n;
        cout << octToDec(n);
    } else if (choice == 6) {
        string n; cout << "Enter hexadecimal: "; cin >> n;
        cout << hexToDec(n);
    } else if (choice == 7) {
        long long n; cout << "Enter binary: "; cin >> n;
        cout << decToOct(binToDec(n));
    } else if (choice == 8) {
        long long n; cout << "Enter binary: "; cin >> n;
        cout << decToHex(binToDec(n));
    } else cout << "Invalid choice";
    return 0;
}
