Here’s a clean **C++ program** (no camel case, no extra text) to find **GCD and LCM** using **functions**:  

```cpp
#include <iostream>
using namespace std;

int gcd(int a, int b) {
    while (b != 0) {
        int t = b;
        b = a % b;
        a = t;
    }
    return a;
}

int lcm(int a, int b) {
    return (a * b) / gcd(a, b);
}

int main() {
    int a, b;
    cout << "Enter two numbers: ";
    cin >> a >> b;
    cout << "GCD: " << gcd(a, b) << endl;
    cout << "LCM: " << lcm(a, b);
    return 0;
}
```

✅ **Formula used:**  
- **GCD** (Greatest Common Divisor) → Euclidean algorithm  
- **LCM** (Least Common Multiple) → `(a * b) / GCD`

