#include <iostream>
using namespace std;

float find_mean(int a[], int n) {
    float sum = 0;
    for (int i = 0; i < n; i++)
        sum += a[i];
    return sum / n;
}

float find_median(int a[], int n) {
    for (int i = 0; i < n - 1; i++)
        for (int j = i + 1; j < n; j++)
            if (a[i] > a[j]) {
                int t = a[i];
                a[i] = a[j];
                a[j] = t;
            }
    if (n % 2 == 0)
        return (a[n / 2 - 1] + a[n / 2]) / 2.0;
    else
        return a[n / 2];
}

int find_mode(int a[], int n) {
    int mode = a[0], max_count = 0;
    for (int i = 0; i < n; i++) {
        int count = 0;
        for (int j = 0; j < n; j++)
            if (a[j] == a[i])
                count++;
        if (count > max_count) {
            max_count = count;
            mode = a[i];
        }
    }
    return mode;
}

int main() {
    int n;
    cout << "Enter number of elements: ";
    cin >> n;
    int a[100];
    cout << "Enter elements: ";
    for (int i = 0; i < n; i++)
        cin >> a[i];

    cout << "Mean: " << find_mean(a, n) << endl;
    cout << "Median: " << find_median(a, n) << endl;
    cout << "Mode: " << find_mode(a, n);
